import React, { useState, useEffect, useRef, useMemo, useCallback, useReducer, createContext, useContext, Component } from 'react';

function App() {
  const [theme, setTheme] = useState('dark');
  return (
    <div>
      <button id="toggle" onClick={() => setTheme(t => t === 'dark' ? 'light' : 'dark')}>
        Toggle
      </button>
      <Section theme={theme} />
    </div>
  );
}

function Section({ theme }) {
  // forgot to forward theme
  return <Card />;
}

function Card({ theme }) {
  // forgot to forward theme
  return <Label />;
}

function Label({ theme }) {
  return <p id="theme">Theme: {theme ?? 'undefined'}</p>;
}

export default App;

