import { describe, test, expect } from 'vitest';
import { render, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import React from 'react';
import App from '../src/App';

const tick = (ms = 20) => new Promise((resolve) => setTimeout(resolve, ms));

describe('The Dropped Prop', () => {
  test('Label shows the initial theme', async () => {
    const { container: root } = render(<App />);
    const el = root.querySelector('#theme');
if (!el) throw new Error('No element with id "theme" found');
if (!el.textContent.includes('dark'))
  throw new Error('Initial label should show "dark" — got: ' + el.textContent);
if (el.textContent.includes('undefined'))
  throw new Error('Label is rendering undefined — the theme value never reached <Label/>');
  });

  test('Toggling updates the deep label', async () => {
    const { container: root } = render(<App />);
    root.querySelector('#toggle').click();
await tick();
const el = root.querySelector('#theme');
if (!el.textContent.includes('light'))
  throw new Error('After toggle, label should show "light" — got: ' + el.textContent);
root.querySelector('#toggle').click();
await tick();
if (!root.querySelector('#theme').textContent.includes('dark'))
  throw new Error('After second toggle, label should be back to "dark"');
  });
});
